using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using ModelContextProtocol;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddHttpClient<WeatherApiClient>(client =>
    {
        client.BaseAddress = new Uri("https://api.open-meteo.com/");
    });

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.Net.Http.Json;
using System.Text.Json.Serialization;

public class WeatherApiClient(HttpClient httpClient)
{
    public async Task<WeatherResponse?> GetCurrentWeatherAsync(
        double latitude, double longitude, CancellationToken ct = default)
    {
        return await httpClient.GetFromJsonAsync<WeatherResponse>(
            $"v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true",
            ct);
    }
}

public record WeatherResponse(
    [property: JsonPropertyName("current_weather")]
    CurrentWeather CurrentWeather);

public record CurrentWeather(
    [property: JsonPropertyName("temperature")]
    double Temperature,
    [property: JsonPropertyName("windspeed")]
    double WindSpeed,
    [property: JsonPropertyName("winddirection")]
    double WindDirection,
    [property: JsonPropertyName("weathercode")]
    int WeatherCode);

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Get current weather for a location by coordinates.")]
    public static async Task<string> GetCurrentWeather(
        WeatherApiClient weatherClient,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var response = await weatherClient.GetCurrentWeatherAsync(latitude, longitude);

        if (response?.CurrentWeather is not { } weather)
        {
            return "Unable to retrieve weather data.";
        }

        return $"""
            Temperature: {weather.Temperature}°C
            Wind Speed:  {weather.WindSpeed} km/h
            Wind Dir:    {weather.WindDirection}°
            Code:        {weather.WeatherCode}
            """;
    }
}

